import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.C2mit3tn.js";const u=JSON.parse('{"title":"Platforms","description":"","frontmatter":{},"headers":[],"relativePath":"guide/platforms.md","filePath":"guide/platforms.md","lastUpdated":1789196459000}'),i={name:"guide/platforms.md"};function s(d,e,l,c,n,m){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="platforms" tabindex="-1">Platforms <a class="header-anchor" href="#platforms" aria-label="Permalink to &quot;Platforms&quot;">​</a></h1><h2 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h2><ul><li><code>minSdk</code> 24, <code>compileSdk</code> 37 (AAR metadata from Compose 1.12 and this library).</li><li>JNI libraries ship inside the AAR. <code>consumer-rules.pro</code> keeps JNI entry points.</li><li>Do not add a second copy of <code>libsweeteditor.so</code>.</li></ul><h2 id="desktop-jvm" tabindex="-1">Desktop (JVM) <a class="header-anchor" href="#desktop-jvm" aria-label="Permalink to &quot;Desktop (JVM)&quot;">​</a></h2><ul><li>JVM 11+.</li><li>First load extracts Core + compose JNI from JAR resources into a per-user cache, then <code>System.load</code>.</li><li>Compose Desktop R8/ProGuard reads <code>META-INF/com.android.tools/r8/</code> from the JAR.</li></ul><h2 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to &quot;iOS&quot;">​</a></h2><ul><li>cinterop statically links <code>libsweeteditor.a</code> for <code>iosArm64</code> and <code>iosSimulatorArm64</code>.</li><li>The host Xcode project must <strong>not</strong> add <code>-lsweeteditor</code> or link any SweetEditor dylib / XCFramework.</li><li>Device and simulator slices are different archives. A device object in the simulator klib fails with “built for iOS while targeting iOS-simulator”.</li></ul><h2 id="web-js-and-wasm" tabindex="-1">Web (JS and Wasm) <a class="header-anchor" href="#web-js-and-wasm" aria-label="Permalink to &quot;Web (JS and Wasm)&quot;">​</a></h2><ul><li>The library injects <code>sweeteditor_web_abi.js</code> and loads <code>sweeteditor_c_abi.{js,wasm}</code> from Compose resources (<code>files/</code>).</li><li>Host <code>index.html</code> does <strong>not</strong> need a manual script tag (0.1.1+).</li><li><code>NativeBridge.isAvailable</code> becomes true after the C ABI module is ready. <code>SweetEditor</code> waits up to ~1800 frames, then shows a load error.</li><li>Keep Compose 1.12.0 so Skiko exports <code>nGetUnresolvedCodepointsCount</code>.</li></ul><h2 id="shared-constraints" tabindex="-1">Shared constraints <a class="header-anchor" href="#shared-constraints" aria-label="Permalink to &quot;Shared constraints&quot;">​</a></h2><p>All targets talk to the same C API. Line/column are 0-based. Colors are packed ARGB <code>Int</code> (<code>0xAARRGGBB</code>).</p>',11)])])}const p=o(i,[["render",s]]);export{u as __pageData,p as default};
